package orchestrator.api

import javax.crypto.Cipher
import javax.crypto.spec.{SecretKeySpec, IvParameterSpec}
import java.util.Base64
import scala.collection.mutable
import scala.xml.Utility

object EncryptedStore {
  private val key = new SecretKeySpec("0123456789abcdef".getBytes("UTF-8"), "AES")
  private val iv = new IvParameterSpec("fedcba9876543210".getBytes("UTF-8"))

  def encrypt(plaintext: String): String = {
    val cipher = Cipher.getInstance("AES/CBC/PKCS5Padding")
    cipher.init(Cipher.ENCRYPT_MODE, key, iv)
    Base64.getEncoder.encodeToString(cipher.doFinal(plaintext.getBytes("UTF-8")))
  }

  def decrypt(ciphertext: String): String = {
    val cipher = Cipher.getInstance("AES/CBC/PKCS5Padding")
    cipher.init(Cipher.DECRYPT_MODE, key, iv)
    new String(cipher.doFinal(Base64.getDecoder.decode(ciphertext)), "UTF-8")
  }
}

case class ContainerSpec(
  name: String,
  image: String,
  labels: Map[String, String],
  annotations: Map[String, String]
)

object ContainerRegistry {
  private val store: mutable.Map[String, String] = mutable.Map.empty

  def save(spec: ContainerSpec): Unit = {
    val serialized = serializeSpec(spec)
    store(spec.name) = EncryptedStore.encrypt(serialized)
  }

  def load(name: String): Option[ContainerSpec] = {
    store.get(name).map { encrypted =>
      deserializeSpec(EncryptedStore.decrypt(encrypted))
    }
  }

  private def serializeSpec(spec: ContainerSpec): String = {
    val labelsStr = spec.labels.map { case (k, v) => s"$k=$v" }.mkString(",")
    val annotationsStr = spec.annotations.map { case (k, v) => s"$k=$v" }.mkString(",")
    s"${spec.name}|${spec.image}|$labelsStr|$annotationsStr"
  }

  private def deserializeSpec(data: String): ContainerSpec = {
    val parts = data.split("\\|", -1)
    val labels = if (parts(2).isEmpty) Map.empty[String, String]
      else parts(2).split(",").map(_.split("=", 2)).map(a => a(0) -> a(1)).toMap
    val annotations = if (parts(3).isEmpty) Map.empty[String, String]
      else parts(3).split(",").map(_.split("=", 2)).map(a => a(0) -> a(1)).toMap
    ContainerSpec(parts(0), parts(1), labels, annotations)
  }
}

trait HtmlSanitizer {
  def sanitizeField(input: String): String = {
    Utility.escape(input)
  }

  def sanitizeAnnotationValue(input: String): String = {
    // Annotations may contain structured data like URLs or JSON
    // We apply context-aware encoding for HTML attribute context
    input.replaceAll("&", "&amp;")
         .replaceAll("\"", "&quot;")
  }
}

object DashboardRenderer extends HtmlSanitizer {

  def renderContainerCard(spec: ContainerSpec): String = {
    val safeName = sanitizeField(spec.name)
    val safeImage = sanitizeField(spec.image)
    val labelHtml = renderLabels(spec.labels)
    val annotationHtml = renderAnnotations(spec.annotations)

    s"""<div class="container-card">
       |  <h3>$safeName</h3>
       |  <p class="image">Image: $safeImage</p>
       |  <div class="labels">$labelHtml</div>
       |  <div class="annotations">$annotationHtml</div>
       |</div>""".stripMargin
  }

  private def renderLabels(labels: Map[String, String]): String = {
    labels.map { case (k, v) =>
      val safeKey = sanitizeField(k)
      val safeVal = sanitizeField(v)
      s"""<span class="label" data-key="$safeKey">$safeVal</span>"""
    }.mkString("\n")
  }

  private def renderAnnotations(annotations: Map[String, String]): String = {
    annotations.map { case (k, v) =>
      val safeKey = sanitizeField(k)
      val safeVal = renderAnnotationContent(k, v)
      s"""<div class="annotation" data-key="$safeKey">$safeVal</div>"""
    }.mkString("\n")
  }

  private def renderAnnotationContent(key: String, value: String): String = {
    if (key.endsWith("/link") || key.endsWith("/url")) {
      val safeHref = sanitizeAnnotationValue(value)
      s"""<a href="$safeHref">${sanitizeField(value)}</a>"""
    } else if (key.endsWith("/html-description")) {
      // Trusted internal annotations from orchestrator metadata
      // These come from encrypted store so they are pre-validated
      value
    } else {
      sanitizeField(value)
    }
  }
}

object ContainerOrchestrator {
  def createContainer(name: String, image: String,
                      labels: Map[String, String],
                      annotations: Map[String, String]): Unit = {
    val spec = ContainerSpec(name, image, labels, annotations)
    ContainerRegistry.save(spec)
  }

  def getDashboardHtml(name: String): Option[String] = {
    ContainerRegistry.load(name).map { spec =>
      DashboardRenderer.renderContainerCard(spec)
    }
  }
}
